login-code.body:
{{ header }}
<div class="bb-main-content"><h2>Verify your sign-in</h2><p>Hello {{ member_name }},</p><p>Your {{ site_title }} sign-in code is:</p><p style="font-size:28px;font-weight:700;margin:24px 0">{{ verification_code }}</p><p>This code expires in 5 minutes. Never share it. If you did not try to sign in, change your password.</p></div>
{{ footer }}

email-verification.body:
{{ header }}
<div class="bb-main-content"><table class="bb-box" cellpadding="0" cellspacing="0"><tr><td class="bb-content"><h2>Verify your account</h2><p>Hello {{ member_name }},</p><p>Use this one-time code to verify your account:</p><p style="font-size:28px;font-weight:700;letter-spacing:6px;margin:24px 0">{{ verification_code }}</p><p>This code expires in {{ expires_in_minutes }} minutes. Never share it with anyone.</p><p>If you did not create this account, you can ignore this email.</p></td></tr></table></div>
{{ footer }}

password-reset-code.body:
{{ header }}
<div class="bb-main-content"><table class="bb-box" cellpadding="0" cellspacing="0"><tr><td class="bb-content"><h2>Reset your password</h2><p>Hello {{ member_name }},</p><p>Use this one-time code to choose a new password:</p><p style="font-size:28px;font-weight:700;letter-spacing:6px;margin:24px 0">{{ verification_code }}</p><p>This code expires in {{ expires_in_minutes }} minutes. Never share it with anyone.</p><p>If you did not request a password reset, no action is needed and your password remains unchanged.</p></td></tr></table></div>
{{ footer }}
